def compute(vars):
    not_yet_leased = vars["v1"]
    total_square_footage = vars["v2"]

    if total_square_footage == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": None, "unit": "percentage"}}}

    value = not_yet_leased / total_square_footage * 100
    return {
        "value": value,
        "trace": {
            "not_yet_leased_square_feet": not_yet_leased,
            "total_square_feet": total_square_footage,
            "output_meta": {"currency": None, "scale": None, "unit": "percentage"}
        }
    }
